INSERT INTO public.query VALUES ('\x00b4d0244a9bc93be70a51477a0cf848e33ed09f9b45e1d9cf3deef97e9cf55e', 71, '{"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT SUM(price + freight_value) AS total_revenue\nFROM olist.order_items;"}],"database":2,"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\x0474226a9f9cf1a21d1fcf4df46a314c9d759040bc8236ef47a64a9a5109d3fe', 80, '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT \n    date_trunc(''month'', o.order_purchase_timestamp) AS order_month,\n    SUM(i.price + i.freight_value) AS monthly_revenue\nFROM olist.orders o\nJOIN olist.order_items i ON o.order_id = i.order_id\nGROUP BY 1\nORDER BY 1;","lib/type":"mbql.stage/native"}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\x16aa201246172c6a2c6c38bef8856db365cd370be6f7d38687dd9fef3ed1aa4a', 46, '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT \n    COALESCE(p.product_category_name, ''unknown'') AS category,\n    SUM(i.price) AS revenue\nFROM olist.order_items i\nJOIN olist.products p ON i.product_id = p.product_id\nGROUP BY 1\nORDER BY revenue DESC\nLIMIT 10;","lib/type":"mbql.stage/native"}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\xe6fbae166c93fe0f04d391679b51ce2b9d7af3e92ebc1ed613cfa7db050f4d17', 118, '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT \n    c.customer_state,\n    COUNT(DISTINCT o.order_id) AS total_orders\nFROM olist.orders o\nJOIN olist.customers c ON o.customer_id = c.customer_id\nGROUP BY 1\nORDER BY total_orders DESC;"}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\x242a7dd58ab2cee673c883a662ef804f097a01c99565eb1ce9a03815367ee193', 16, '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT \n    date_trunc(''month'', order_purchase_timestamp) AS month,\n    hour(AVG(order_delivered_customer_date - order_purchase_timestamp)) AS avg_delivery_time\nFROM olist.orders\nWHERE order_status = ''delivered''\n  AND order_delivered_customer_date IS NOT NULL\nGROUP BY 1\nORDER BY 1;","lib/type":"mbql.stage/native"}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\xd52d22ea581eae60b4363e7164e9b4b7223b06d58fc14b3c4a13534d8d3ae9be', 44, '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT \n    date_trunc(''month'', order_purchase_timestamp) AS month,\n    AVG(order_delivered_customer_date - order_purchase_timestamp) AS avg_delivery_time\nFROM olist.orders\nWHERE order_status = ''delivered''\n  AND order_delivered_customer_date IS NOT NULL\nGROUP BY 1\nORDER BY 1;","lib/type":"mbql.stage/native"}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\x8ae5c4efd980f00e05086e57fd4a46ad2c8fba133efd2805f6a9a1f93e75411d', 42, '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT \n    date_trunc(''month'', order_purchase_timestamp) AS month,\n    ROUND(\n        EXTRACT(EPOCH FROM AVG(order_delivered_customer_date - order_purchase_timestamp)) / 86400, \n        1\n    ) AS avg_delivery_days\nFROM olist.orders\nWHERE order_status = ''delivered''\n  AND order_delivered_customer_date IS NOT NULL\nGROUP BY 1\nORDER BY 1;"}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\x6f08bec0bd83ce2302d959105d374fc77841ecae5cbfef94ecc0627a52275861', 44, '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT \n    date_trunc(''month'', order_purchase_timestamp) AS month,\n    ROUND(EXTRACT(EPOCH FROM AVG(order_delivered_customer_date - order_purchase_timestamp)) / 86400, 1) AS avg_delivery_days\nFROM olist.orders\nWHERE order_status = ''delivered''\n  AND order_delivered_customer_date IS NOT NULL\nGROUP BY 1\nORDER BY 1;","lib/type":"mbql.stage/native"}],"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');
INSERT INTO public.query VALUES ('\x7f7ae809c762b71fce523236afd76214b1b8fef194d6ce0597e17203105c43dc', 51, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT \n    COALESCE(p.product_category_name, ''unknown'') AS category,\n    SUM(i.price) AS revenue\nFROM olist.order_items i\nJOIN olist.products p ON i.product_id = p.product_id\nGROUP BY 1\nORDER BY revenue DESC\nLIMIT 10;"}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"database":2}');
