INSERT INTO public.query VALUES ('\x7adfc73d5d030233b77c49b6dd31e1bb7e17a02d5b2332911b48ca1c3534d616', 43, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT \n    date_trunc(''month'', order_purchase_timestamp) AS month,\n    ROUND(EXTRACT(EPOCH FROM AVG(order_delivered_customer_date - order_purchase_timestamp)) / 86400, 1) AS avg_delivery_days\nFROM olist.orders\nWHERE order_status = ''delivered''\n  AND order_delivered_customer_date IS NOT NULL\nGROUP BY 1\nORDER BY 1;"}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"database":2}');
INSERT INTO public.query VALUES ('\x23b9135970ca6d4b0f39e31a26f030f3d14f5fa3ce00d2646594b8d3f267ba2a', 29, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","stages":[{"native":"SELECT SUM(price + freight_value) AS total_revenue\nFROM olist.order_items;","lib/type":"mbql.stage/native"}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"database":2}');
INSERT INTO public.query VALUES ('\x209d9026ec07a4df736858947c64e8b3dc558a256010d2457c3833165f651bd8', 114, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"lib/type":"mbql/query","stages":[{"native":"SELECT \n    c.customer_state,\n    COUNT(DISTINCT o.order_id) AS total_orders\nFROM olist.orders o\nJOIN olist.customers c ON o.customer_id = c.customer_id\nGROUP BY 1\nORDER BY total_orders DESC;","lib/type":"mbql.stage/native"}],"middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"database":2}');
INSERT INTO public.query VALUES ('\x71e212babf07d50cbd52bc7987b1c1a4371836a3419c7f4ebff487c5f8c15c35', 40, '{"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/mbql","source-table":13,"aggregation":[["count",{"lib/uuid":"e7f4da7d-2182-400a-ae16-3f7814b6a5f8"}]],"breakout":[["field",{"lib/uuid":"e21795b7-12f3-45c1-9547-a5b02c3e76b0","effective-type":"type/Integer","base-type":"type/Integer","binning":{"strategy":"default"}},74]]}],"database":2,"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');


