INSERT INTO public.report_card VALUES (37, '2026-10-20 20:22:52.980454+00', '2026-10-20 20:22:52.980454+00', 'Aerodynamic Copper Knife trend', 'Compares the total number of orders placed for this product this month with the previous period', 'smartscalar', '{"database":1,"query":{"aggregation":[["sum",["field",2,{"base-type":"type/Integer"}]]],"breakout":[["field",13,{"base-type":"type/DateTime","temporal-unit":"month"}]],"filter":["and",["between",["field",13,{"base-type":"type/DateTime"}],"2024-01-01","2027-01-23"],["=",["field",14,{"base-type":"type/Integer"}],165]],"source-table":2},"type":"query"}', '{"column_settings":null}', 13371338, 1, 2, 'query', false, 2, NULL, NULL, false, NULL, NULL, '[{"base_type":"type/DateTime","coercion_strategy":null,"description":"The date and time an order was submitted.","display_name":"Created At: Month","effective_type":"type/DateTime","field_ref":["field",13,{"base-type":"type/DateTime","temporal-unit":"month"}],"fk_target_field_id":null,"id":13,"name":"CREATED_AT","semantic_type":"type/CreationTimestamp","settings":{"time_enabled":"milliseconds"},"unit":"month","visibility_type":"normal"},{"base_type":"type/BigInteger","display_name":"Sum of Quantity","effective_type":"type/BigInteger","field_ref":["aggregation",0],"name":"sum","semantic_type":"type/Quantity","settings":{"show_mini_bar":false}}]', NULL, 'BQAQ6YNiUIMfmAPLpSKQW', '[]', '[]', true, NULL, 'question', NULL, NULL, '2026-10-20 20:22:52.980454+00', 0, false, NULL, NULL, NULL, 20, NULL, 0, '{"database":1,"query":{"aggregation":[["sum",["field",2,{"base-type":"type/Integer"}]]],"breakout":[["field",13,{"base-type":"type/DateTime","temporal-unit":"month"}]],"filter":["and",["between",["field",13,{"base-type":"type/DateTime"}],"2024-01-01","2027-01-23"],["=",["field",14,{"base-type":"type/Integer"}],165]],"source-table":2},"type":"query"}', NULL, NULL);
INSERT INTO public.report_card VALUES (38, '2026-10-31 13:42:34.029562+00', '2026-10-31 13:42:34.029562+00', 'Total Revenue', 'Сколько денег принес магазин всего.', 'scalar', '{"lib/type":"mbql/query","stages":[{"native":"SELECT SUM(price + freight_value) AS total_revenue\nFROM olist.order_items;","lib/type":"mbql.stage/native"}],"database":2}', '{}', 1, 2, NULL, 'native', false, 7, NULL, NULL, false, NULL, NULL, '[{"database_type":"numeric","semantic_type":null,"lib/deduplicated-name":"total_revenue","lib/original-name":"total_revenue","name":"total_revenue","lib/source":"source/native","lib/source-column-alias":"total_revenue","source":"native","field_ref":["field","total_revenue",{"base-type":"type/Decimal"}],"effective_type":"type/Decimal","lib/desired-column-alias":"total_revenue","display_name":"total_revenue","fingerprint":{"global":{"distinct-count":1,"nil%":0.0},"type":{"type/Number":{"min":1.584355324E7,"q1":1.584355324E7,"q3":1.584355324E7,"max":1.584355324E7,"sd":null,"avg":1.584355324E7}}},"base_type":"type/Decimal"}]', NULL, 'QvOL8santqraxXdapHAHG', '[]', '[]', true, 'v0.58.35 (5335058)', 'question', NULL, NULL, '2026-10-31 13:57:58.805805+00', 3, false, NULL, NULL, NULL, 23, NULL, 0, NULL, NULL, NULL);
INSERT INTO public.report_card VALUES (39, '2026-10-31 13:43:36.961458+00', '2026-10-31 13:43:59.527833+00', 'Revenue over Time', 'Растет бизнес или падает, есть ли сезонность.', 'line', '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT \n    date_trunc(''month'', o.order_purchase_timestamp) AS order_month,\n    SUM(i.price + i.freight_value) AS monthly_revenue\nFROM olist.orders o\nJOIN olist.order_items i ON o.order_id = i.order_id\nGROUP BY 1\nORDER BY 1;"}]}', '{"table.cell_column":"monthly_revenue","graph.x_axis.scale":"timeseries","graph.dimensions":["order_month"],"graph.metrics":["monthly_revenue"]}', 1, 2, NULL, 'native', false, 7, NULL, NULL, false, NULL, NULL, '[{"database_type":"timestamp","semantic_type":null,"lib/deduplicated-name":"order_month","lib/original-name":"order_month","name":"order_month","lib/source":"source/native","lib/source-column-alias":"order_month","source":"native","field_ref":["field","order_month",{"base-type":"type/DateTime"}],"effective_type":"type/DateTime","lib/desired-column-alias":"order_month","display_name":"order_month","fingerprint":{"global":{"distinct-count":24,"nil%":0.0},"type":{"type/DateTime":{"earliest":"2016-09-01T00:00:00Z","latest":"2018-09-01T00:00:00Z"}}},"base_type":"type/DateTime"},{"database_type":"numeric","semantic_type":null,"lib/deduplicated-name":"monthly_revenue","lib/original-name":"monthly_revenue","name":"monthly_revenue","lib/source":"source/native","lib/source-column-alias":"monthly_revenue","source":"native","field_ref":["field","monthly_revenue",{"base-type":"type/Decimal"}],"effective_type":"type/Decimal","lib/desired-column-alias":"monthly_revenue","display_name":"monthly_revenue","fingerprint":{"global":{"distinct-count":24,"nil%":0.0},"type":{"type/Number":{"min":19.62,"q1":349351.43,"q3":1040702.5700000001,"max":1179143.77,"sd":417476.19928952697,"avg":660148.0516666666}}},"base_type":"type/Decimal"}]', NULL, '-f_CZf4tmSc46z77gJrzv', '[]', '[]', true, 'v0.58.35 (5335058)', 'question', NULL, '2026-10-31 13:43:59.532078+00', '2026-10-31 13:57:58.805805+00', 2, false, NULL, NULL, NULL, 23, NULL, 0, NULL, NULL, NULL);
INSERT INTO public.report_card VALUES (42, '2026-10-31 13:47:31.348581+00', '2026-10-31 13:54:30.806215+00', 'Average Delivery Time', 'Насколько быстро доставляются заказы (разница между покупкой и фактической доставкой).', 'line', '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT \n    date_trunc(''month'', order_purchase_timestamp) AS month,\n    ROUND(EXTRACT(EPOCH FROM AVG(order_delivered_customer_date - order_purchase_timestamp)) / 86400, 1) AS avg_delivery_days\nFROM olist.orders\nWHERE order_status = ''delivered''\n  AND order_delivered_customer_date IS NOT NULL\nGROUP BY 1\nORDER BY 1;"}]}', '{"graph.x_axis.scale":"ordinal","graph.dimensions":["month"],"graph.metrics":["avg_delivery_days"],"graph.series_order_dimension":null,"graph.series_order":null,"graph.y_axis.title_text":"avg_delivery_time"}', 1, 2, NULL, 'native', false, 7, NULL, NULL, false, NULL, NULL, '[{"database_type":"timestamp","semantic_type":null,"lib/deduplicated-name":"month","lib/original-name":"month","name":"month","lib/source":"source/native","lib/source-column-alias":"month","source":"native","field_ref":["field","month",{"base-type":"type/DateTime"}],"effective_type":"type/DateTime","lib/desired-column-alias":"month","display_name":"month","fingerprint":{"global":{"distinct-count":23,"nil%":0.0},"type":{"type/DateTime":{"earliest":"2016-09-01T00:00:00Z","latest":"2018-08-01T00:00:00Z"}}},"base_type":"type/DateTime"},{"database_type":"numeric","semantic_type":null,"lib/deduplicated-name":"avg_delivery_days","lib/original-name":"avg_delivery_days","name":"avg_delivery_days","lib/source":"source/native","lib/source-column-alias":"avg_delivery_days","source":"native","field_ref":["field","avg_delivery_days",{"base-type":"type/Decimal"}],"effective_type":"type/Decimal","lib/desired-column-alias":"avg_delivery_days","display_name":"avg_delivery_days","fingerprint":{"global":{"distinct-count":22,"nil%":0.0},"type":{"type/Number":{"min":4.7,"q1":11.325000000000001,"q3":15.125,"max":54.8,"sd":9.38255887629775,"avg":14.317391304347826}}},"base_type":"type/Decimal"}]', NULL, 'RhOc3gNh9_Wc0SbHvnd_h', '[]', '[]', true, 'v0.58.35 (5335058)', 'question', NULL, '2026-10-31 13:54:30.807368+00', '2026-10-31 14:32:22.750795+00', 4, false, NULL, NULL, NULL, 23, NULL, 0, NULL, NULL, NULL);
INSERT INTO public.report_card VALUES (40, '2026-10-31 13:45:23.908584+00', '2026-10-31 13:45:23.908584+00', 'Top Product Categories', 'Какие товары приносят больше всего денег.', 'bar', '{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT \n    COALESCE(p.product_category_name, ''unknown'') AS category,\n    SUM(i.price) AS revenue\nFROM olist.order_items i\nJOIN olist.products p ON i.product_id = p.product_id\nGROUP BY 1\nORDER BY revenue DESC\nLIMIT 10;"}]}', '{"graph.x_axis.scale":"ordinal","graph.dimensions":["category"],"graph.metrics":["revenue"]}', 1, 2, NULL, 'native', false, 7, NULL, NULL, false, NULL, NULL, '[{"database_type":"varchar","semantic_type":null,"lib/deduplicated-name":"category","lib/original-name":"category","name":"category","lib/source":"source/native","lib/source-column-alias":"category","source":"native","field_ref":["field","category",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"category","display_name":"category","fingerprint":{"global":{"distinct-count":10,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":15.5}}},"base_type":"type/Text"},{"database_type":"numeric","semantic_type":null,"lib/deduplicated-name":"revenue","lib/original-name":"revenue","name":"revenue","lib/source":"source/native","lib/source-column-alias":"revenue","source":"native","field_ref":["field","revenue",{"base-type":"type/Decimal"}],"effective_type":"type/Decimal","lib/desired-column-alias":"revenue","display_name":"revenue","fingerprint":{"global":{"distinct-count":10,"nil%":0.0},"type":{"type/Number":{"min":485256.46,"q1":632248.66,"q3":1036988.68,"max":1258681.34,"sd":270402.12948780775,"avg":847595.756}}},"base_type":"type/Decimal"}]', NULL, 'KQ5pHj3GIgRKS0s20Seh8', '[]', '[]', true, 'v0.58.35 (5335058)', 'question', NULL, NULL, '2026-10-31 13:57:58.805805+00', 3, false, NULL, NULL, NULL, 23, NULL, 0, NULL, NULL, NULL);
INSERT INTO public.report_card VALUES (41, '2026-10-31 13:46:31.706546+00', '2026-10-31 13:46:31.706546+00', 'Orders by State', 'В каких штатах Бразилии больше всего покупателей.', 'row', '{"lib/type":"mbql/query","database":2,"stages":[{"native":"SELECT \n    c.customer_state,\n    COUNT(DISTINCT o.order_id) AS total_orders\nFROM olist.orders o\nJOIN olist.customers c ON o.customer_id = c.customer_id\nGROUP BY 1\nORDER BY total_orders DESC;","lib/type":"mbql.stage/native"}]}', '{"graph.x_axis.scale":"ordinal","graph.dimensions":["customer_state"],"graph.metrics":["total_orders"]}', 1, 2, NULL, 'native', false, 7, NULL, NULL, false, NULL, NULL, '[{"database_type":"varchar","semantic_type":null,"lib/deduplicated-name":"customer_state","lib/original-name":"customer_state","name":"customer_state","lib/source":"source/native","lib/source-column-alias":"customer_state","source":"native","field_ref":["field","customer_state",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"customer_state","display_name":"customer_state","fingerprint":{"global":{"distinct-count":27,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.2222222222222222,"average-length":2.0}}},"base_type":"type/Text"},{"database_type":"int8","semantic_type":null,"lib/deduplicated-name":"total_orders","lib/original-name":"total_orders","name":"total_orders","lib/source":"source/native","lib/source-column-alias":"total_orders","source":"native","field_ref":["field","total_orders",{"base-type":"type/BigInteger"}],"effective_type":"type/BigInteger","lib/desired-column-alias":"total_orders","display_name":"total_orders","fingerprint":{"global":{"distinct-count":27,"nil%":0.0},"type":{"type/Number":{"min":46.0,"q1":365.75,"q3":3070.0,"max":41746.0,"sd":8270.437663984063,"avg":3683.0}}},"base_type":"type/BigInteger"}]', NULL, '4NYpXgkiqR0uCOoT8Wgwf', '[]', '[]', true, 'v0.58.35 (5335058)', 'question', NULL, NULL, '2026-10-31 13