INSERT INTO public.revision VALUES (1, 'Card', 38, 1, '2026-10-31 13:42:34.057004+00', '{"description":"Сколько денег принес магазин всего.","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"collection_id":7,"query_type":"native","name":"Total Revenue","type":"question","cache_ttl":null,"dataset_query":{"stages":[{"native":"SELECT SUM(price + freight_value) AS total_revenue\nFROM olist.order_items;","lib/type":"mbql.stage/native"}],"lib/type":"mbql/query","database":2},"parameter_mappings":[],"display":"scalar","archived_directly":false,"collection_preview":true,"visualization_settings":{},"parameters":[],"dashboard_id":null}', false, true, NULL, true, 'v0.58.35 (5335058)');
INSERT INTO public.revision VALUES (3, 'Card', 39, 1, '2026-10-31 13:43:59.561748+00', '{"description":"Растет бизнес или падает, есть ли сезонность.","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"collection_id":7,"query_type":"native","name":"Revenue over Time","type":"question","cache_ttl":null,"dataset_query":{"database":2,"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT \n    date_trunc(''month'', o.order_purchase_timestamp) AS order_month,\n    SUM(i.price + i.freight_value) AS monthly_revenue\nFROM olist.orders o\nJOIN olist.order_items i ON o.order_id = i.order_id\nGROUP BY 1\nORDER BY 1;"}]},"parameter_mappings":[],"display":"line","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.cell_column":"monthly_revenue","graph.x_axis.scale":"timeseries","graph.dimensions":["order_month"],"graph.metrics":["monthly_revenue"]},"parameters":[],"dashboard_id":null}', false, false, NULL, true, 'v0.58.35 (5335058)');
INSERT INTO public.revision VALUES (2, 'Card', 39, 1, '2026-10-31 13:43:36.970783+00', '{"description":"Растет бизнес или падает, есть ли сезонность.","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"collection_id":7,"query_type":"native","name":"Revenue over Time","type":"question","cache_ttl":null,"dataset_query":{"database":2,"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT \n    date_trunc(''month'', o.order_purchase_timestamp) AS order_month,\n    SUM(i.price + i.freight_value) AS monthly_revenue\nFROM olist.orders o\nJOIN olist.order_items i ON o.order_id = i.order_id\nGROUP BY 1\nORDER BY 1;"}]},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.cell_column":"monthly_revenue"},"parameters":[],"dashboard_id":null}', false, true, NULL, false, 'v0.58.35 (5335058)');
INSERT INTO public.revision VALUES (4, 'Card', 40, 1, '2026-10-31 13:45:23.918689+00', '{"description":"Какие товары приносят больше всего денег.","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"collection_id":7,"query_type":"native","name":"Top Product Categories","type":"question","cache_ttl":null,"dataset_query":{"database":2,"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT \n    COALESCE(p.product_category_name, ''unknown'') AS category,\n    SUM(i.price) AS revenue\nFROM olist.order_items i\nJOIN olist.products p ON i.product_id = p.product_id\nGROUP BY 1\nORDER BY revenue DESC\nLIMIT 10;"}]},"parameter_mappings":[],"display":"bar","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.x_axis.scale":"ordinal","graph.dimensions":["category"],"graph.metrics":["revenue"]},"parameters":[],"dashboard_id":null}', false, true, NULL, true, 'v0.58.35 (5335058)');
INSERT INTO public.revision VALUES (5, 'Card', 41, 1, '2026-10-31 13:46:31.716342+00', '{"description":"В каких штатах Бразилии больше всего покупателей.","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"collection_id":7,"query_type":"native","name":"Orders by State","type":"question","cache_ttl":null,"dataset_query":{"database":2,"lib/type":"mbql/query","stages":[{"native":"SELECT \n    c.customer_state,\n    COUNT(DISTINCT o.order_id) AS total_orders\nFROM olist.orders o\nJOIN olist.customers c ON o.customer_id = c.customer_id\nGROUP BY 1\nORDER BY total_orders DESC;","lib/type":"mbql.stage/native"}]},"parameter_mappings":[],"display":"row","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.x_axis.scale":"ordinal","graph.dimensions":["customer_state"],"graph.metrics":["total_orders"]},"parameters":[],"dashboard_id":null}', false, true, NULL, true, 'v0.58.35 (5335058)');
INSERT INTO public.revision VALUES (7, 'Card', 42, 1, '2026-10-31 13:54:30.82061+00', '{"description":"Насколько быстро доставляются заказы (разница между покупкой и фактической доставкой).","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"collection_id":7,"query_type":"native","name":"Average Delivery Time","type":"question","cache_ttl":null,"dataset_query":{"database":2,"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT \n    date_trunc(''month'', order_purchase_timestamp) AS month,\n    ROUND(EXTRACT(EPOCH FROM AVG(order_delivered_customer_date - order_purchase_timestamp)) / 86400, 1) AS avg_delivery_days\nFROM olist.orders\nWHERE order_status = ''delivered''\n  AND order_delivered_customer_date IS NOT NULL\nGROUP BY 1\nORDER BY 1;"}]},"parameter_mappings":[],"display":"line","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.x_axis.scale":"ordinal","graph.dimensions":["month"],"graph.series_order_dimension":null,"graph.series_order":null,"graph.y_axis.title_text":"avg_delivery_time","graph.metrics":["avg_delivery_days"]},"parameters":[],"dashboard_id":null}', false, false, NULL, true, 'v0.58.35 (5335058)');
INSERT INTO public.revision VALUES (6, 'Card', 42, 1, '2026-10-31 13:47:31.360189+00', '{"description":"Насколько быстро доставляются заказы (разница между покупкой и фактической доставкой).","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"dependency_analysis_version":0,"card_schema":23,"database_id":2,"collection_id":7,"query_type":"native","name":"Average Delivery Time","type":"question","cache_ttl":null,"dataset_query":{"database":2,"lib/type":"mbql/query","stages":[{"lib/type":"mbql.stage/native","native":"SELECT \n    date_trunc(''month'', order_purchase_timestamp) AS month,\n    AVG(order_delivered_customer_date - order_purchase_timestamp) AS avg_delivery_time\nFROM olist.orders\nWHERE order_status = ''delivered''\n  AND order_delivered_customer_date IS NOT NULL\nGROUP BY 1\nORDER BY 1;"}]},"parameter_mappings":[],"display":"line","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.x_axis.scale":"ordinal","graph.dimensions":["month","avg_delivery_time"],"graph.metrics":[null]},"parameters":[],"dashboard_id":null}', false, true, NULL, false, 'v0.58.35 (5335058)');
